import AppKit

/// Every save of the package announced to the cache ledger, so no marker,
/// waveform or voice file lands between the save's listing and its swap
/// (`MediaImporter.CacheLedger`, `MediaCacheLedger.swift`).
///
/// This one override is enough: ⌘S, Save As, autosave and `save_project`
/// all funnel through `save(to:ofType:for:completionHandler:)`, and NSDocument
/// lists the package for its lazy `cache/` wrapper and swaps the new package
/// in before that completion runs. `saveBegan` waits for a publication
/// already being written; `saveEnded` runs before the caller's handler.
extension ProjectDocument {
    override func save(
        to url: URL, ofType typeName: String, for saveOperation: NSDocument.SaveOperationType,
        completionHandler: @escaping ((any Error)?) -> Void
    ) {
        guard let directory = intendedCacheDirectory else {
            super.save(to: url, ofType: typeName, for: saveOperation,
                       completionHandler: completionHandler)
            return
        }
        let save = MediaImporter.CacheLedger.shared.saveBegan(cacheDir: directory)
        super.save(to: url, ofType: typeName, for: saveOperation) { error in
            MediaImporter.CacheLedger.shared.saveEnded(cacheDir: directory, save: save)
            completionHandler(error)
        }
    }
}

//! The two scales a new clip can be placed at — Fit and Fill — and nothing
//! else.
//!
//! Cut out of `edit_clip.rs` under the size rule, a pure move (road map
//! "audio" AP9's toll, `designs/adr/core-file-history.md`): `edit_clip.rs`
//! decides where a clip sits, and these two decide how big a new one is
//! drawn. Fit is a RESCUE for oversized footage and honours
//! `canvas.fit_new_clips`; Fill is a REQUIREMENT, ignores it, scales up as
//! readily as down and clamps to `SCALE_MAX`.

use crate::model::Project;
use crate::props_check::{SCALE_MAX, SCALE_MIN};

impl Project {
    /// Fit scale for a new clip: `min(cw/sw, ch/sh)` when `fit_new_clips`
    /// is on and the source exceeds the canvas, else 1 (spec §5.3). A
    /// source that already fits is never scaled UP — Fit is a rescue for
    /// oversized footage, not a stretch.
    pub(crate) fn fit_scale(&self, source_width: f64, source_height: f64) -> f64 {
        if !(self.canvas.fit_new_clips && source_width > 0.0 && source_height > 0.0) {
            return 1.0;
        }
        let canvas_width = f64::from(self.canvas.width);
        let canvas_height = f64::from(self.canvas.height);
        if source_width <= canvas_width && source_height <= canvas_height {
            return 1.0;
        }
        let scale = (canvas_width / source_width).min(canvas_height / source_height);
        if scale.is_finite() {
            scale.clamp(SCALE_MIN, SCALE_MAX)
        } else {
            1.0
        }
    }

    /// Fill scale: `max(cw/sw, ch/sh)`, the smallest scale that leaves no
    /// canvas showing — [`Project::fit_scale`]'s sibling, and what
    /// `edit_background.rs` gives a backdrop.
    ///
    /// Three differences from Fit, all of them one difference read three
    /// ways: Fit is a RESCUE for oversized footage and Fill is a
    /// REQUIREMENT. So it ignores `canvas.fit_new_clips` — a backdrop that
    /// leaves a bar down the side has failed at its one job whatever that
    /// flag says; it scales UP as readily as down, a source smaller than the
    /// canvas being exactly the case that needs it; and it clamps HERE, so
    /// no caller can store a scale `check_video` would refuse. The clamp's
    /// visible cost is `edit_zoom.rs`'s, for the same constant: on a
    /// 1920-wide canvas a source under 192 pixels cannot reach the edge, and
    /// what comes back is the biggest legal magnification rather than a
    /// refusal. A degenerate source has no ratio to take and answers 1;
    /// callers refuse one by name before they ever reach this.
    pub(crate) fn fill_scale(&self, source_width: f64, source_height: f64) -> f64 {
        let scale = (f64::from(self.canvas.width) / source_width)
            .max(f64::from(self.canvas.height) / source_height);
        if scale.is_finite() && scale > 0.0 {
            scale.clamp(SCALE_MIN, SCALE_MAX)
        } else {
            1.0
        }
    }
}
//! Frame-grid normalization shared by clip transfer and canvas edits.

use crate::model::{Clip, Project};
use crate::recipe_graphic::graphic_resnapped;
use crate::speed_map::{end_speed, is_ramped};

/// Re-snaps a clip's actions onto this project's frame grid and
/// clamps them inside its (already re-snapped) duration.
///
/// The same clamps serve canvas, paste and unnest: yesterday's grid is not
/// today's, a
/// duration that rounds to zero is what `validate` rejects, and an action
/// must still fit the clip it is on.
///
/// On a RAMPED clip a SPEED action is snapped but not clamped into the
/// clip: one running past the end keeps running past it, as `trim_end`
/// leaves it, so S∞ and what the clip reads by its end are kept up to the
/// grid's rounding (spec §11 SR-19 (g)). Every other action clamps.
pub(crate) fn resnap_actions(project: &Project, clip: &mut Clip) {
    let frame = project.frame();
    let last_start = clip.duration.saturating_sub(frame).max(0);
    let ramped = is_ramped(clip);
    for action in clip.actions.iter_mut() {
        if ramped && end_speed(action).is_some() {
            action.start = project.snapped(action.start).max(0);
            action.duration = project.snapped(action.duration).max(frame).max(1);
            continue;
        }
        action.start = project.snapped(action.start).clamp(0, last_start);
        action.duration = project
            .snapped(action.duration)
            .max(frame)
            .min(clip.duration.saturating_sub(action.start))
            .max(1);
    }
}

impl Project {
    /// Normalize one clip after its source IDs and caller-specific placement
    /// have been resolved. Source positions and audio envelopes are separate
    /// clocks and are deliberately left alone; a graphic's `in` and `length`
    /// are the canvas's frames, so they re-snap through `graphic_resnapped`
    /// (spec §11 G-18·b).
    ///
    /// A RAMPED clip's duration is held a second time, against its
    /// re-snapped speed actions, whose new grid can make it read more, and
    /// its other actions are re-clamped into what is left (spec §11 SR-19
    /// (g)).
    pub(crate) fn resnap_clip_times(&self, clip: &mut Clip) {
        clip.start = self.snapped(clip.start).max(0);
        clip.duration = self.duration_resnapped(clip);
        resnap_actions(self, clip);
        if is_ramped(clip) {
            clip.duration = self.duration_resnapped(clip);
            resnap_actions(self, clip);
        }
        if let Some(video) = clip.video.as_mut() {
            self.snap_motion(video);
        }
        if let Some(text) = clip.text.as_mut() {
            self.snap_animation(text);
        }
        clip.graphic = graphic_resnapped(clip.graphic.as_ref(), self);
    }
}
